            "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" font-size=\"36\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Buried at Qunu</text><text x=\"550\" y=\"115\" font-size=\"24\" fill=\"#9ca3af\" text-anchor=\"middle\">December 15, 2013 — the long walk's end</text><rect x=\"80\" y=\"170\" width=\"940\" height=\"200\" fill=\"#16213e\" stroke=\"#6366f1\" stroke-width=\"3\" rx=\"10\"/><text x=\"550\" y=\"210\" font-size=\"26\" fill=\"#6366f1\" text-anchor=\"middle\" font-weight=\"bold\">The Place</text><text x=\"550\" y=\"250\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Qunu — Eastern Cape village in former Transkei</text><text x=\"550\" y=\"284\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Where Mandela's mother raised him after father's death</text><text x=\"550\" y=\"318\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">The rural hillsides of his boyhood</text><text x=\"550\" y=\"352\" font-size=\"18\" fill=\"#9ca3af\" text-anchor=\"middle\">Same landscape he had herded cattle in at age 10</text><rect x=\"80\" y=\"400\" width=\"940\" height=\"200\" fill=\"#16213e\" stroke=\"#8b5cf6\" stroke-width=\"3\" rx=\"10\"/><text x=\"550\" y=\"440\" font-size=\"26\" fill=\"#8b5cf6\" text-anchor=\"middle\" font-weight=\"bold\">The Wish</text><text x=\"550\" y=\"480\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Mandela had stated repeatedly:</text><text x=\"550\" y=\"514\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\" font-style=\"italic\">\"I want to be buried in the place of my forefathers.\"</text><text x=\"550\" y=\"548\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Family graveyard at Qunu — his ancestors</text><text x=\"550\" y=\"582\" font-size=\"18\" fill=\"#9ca3af\" text-anchor=\"middle\">Not Pretoria, not Robben Island, not Soweto</text><rect x=\"80\" y=\"630\" width=\"940\" height=\"200\" fill=\"#16213e\" stroke=\"#10b981\" stroke-width=\"3\" rx=\"10\"/><text x=\"550\" y=\"670\" font-size=\"26\" fill=\"#10b981\" text-anchor=\"middle\" font-weight=\"bold\">The Service</text><text x=\"550\" y=\"710\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Private — family only</text><text x=\"550\" y=\"744\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Combined Christian liturgy with Thembu rites</text><text x=\"550\" y=\"778\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">21-gun salute by SA National Defence Force</text><text x=\"550\" y=\"812\" font-size=\"18\" fill=\"#9ca3af\" text-anchor=\"middle\">Graça, Zenani, Zindzi, grandchildren present</text><rect x=\"80\" y=\"860\" width=\"940\" height=\"160\" fill=\"#16213e\" stroke=\"#f59e0b\" stroke-width=\"3\" rx=\"10\"/><text x=\"550\" y=\"900\" font-size=\"26\" fill=\"#f59e0b\" text-anchor=\"middle\" font-weight=\"bold\">The Circle Closed</text><text x=\"550\" y=\"940\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Born Mvezo 1918, raised Qunu, buried Qunu 2013</text><text x=\"550\" y=\"974\" font-size=\"22\" fill=\"#ec4899\" text-anchor=\"middle\" font-style=\"italic\">A 95-year arc completed on the hillsides he began on</text><text x=\"550\" y=\"1004\" font-size=\"18\" fill=\"#9ca3af\" text-anchor=\"middle\">The long walk to freedom returned to where it started</text></svg>",
